import{_ as e}from"./chunks/world.CuTOnk9q.js";import{_ as t,o as i,c as r,a2 as l}from"./chunks/framework.CqGS6Fr9.js";const u=JSON.parse('{"title":"Добро пожаловать","description":"","frontmatter":{"pageId":"index","contentRevision":1},"headers":[],"relativePath":"ru/index.md","filePath":"ru/index.md"}'),s={name:"ru/index.md"};function o(n,a,d,h,c,p){return i(),r("div",null,[...a[0]||(a[0]=[l('<h1 id="добро-пожаловать" tabindex="-1">Добро пожаловать <a class="header-anchor" href="#добро-пожаловать" aria-label="Permalink to &quot;Добро пожаловать&quot;">​</a></h1><p>Применимость: Rimlink 0.8.1 · RimWorld 1.7 · протокол 1.</p><img class="wiki-art" src="'+e+'" alt="Общий мир. Собственная колония. Новые связи." width="960" height="440"><p class="wiki-caption">Общий мир. Собственная колония. Новые связи.</p><h2 id="usage" tabindex="-1">Как пользоваться <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Как пользоваться {#usage}&quot;">​</a></h2><p>Rimlink — постоянный мультиплеер для RimWorld 1.7. Колонии живут на общем серверном мире, но каждая домашняя карта симулируется своим игроком. Это не непрерывная синхронизация всех колоний.</p><p><strong>Первый вход:</strong> установка → подключение → создание колонии → сохранение. Начни с руководства новичка. Владельцу сервера нужен административный маршрут; участнику разработки — архитектура и сборка. В боковом меню находятся все статьи, поиск работает локально. Язык переключается в верхней панели.</p><h2 id="limits" tabindex="-1">Ограничения и безопасность <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Ограничения и безопасность {#limits}&quot;">​</a></h2><p>Вики описывает 0.8.1, протокол 1. Настройки конкретного сервера могут отличаться от значений по умолчанию. Будущие аванпосты и захват территорий не входят в текущие возможности.</p><h2 id="related" tabindex="-1">См. также <a class="header-anchor" href="#related" aria-label="Permalink to &quot;См. также {#related}&quot;">​</a></h2><ul><li><a href="./players/getting-started">Первый сеанс</a></li><li><a href="./admins/getting-started">Первый сервер</a></li><li><a href="./developers/architecture">Архитектура</a></li></ul>',11)])])}const f=t(s,[["render",o]]);export{u as __pageData,f as default};
